package com.bytebazaar.api;import java.math.BigDecimal;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/products") @CrossOrigin(origins={"http://localhost:3000","http://localhost:5173"}) public class ProductController{private final List<Product>products=List.of(new Product(1L,"NovaBook Air 14","Laptops",new BigDecimal("899.99"),"M3 • 16GB • 512GB"),new Product(2L,"Aether RTX 4070","Components",new BigDecimal("579.99"),"12GB GDDR6X"),new Product(3L,"Pulse Pro Wireless","Gaming",new BigDecimal("89.99"),"26K DPI • 70 hr"),new Product(4L,"ArcView 27-inch 4K","Monitors",new BigDecimal("349.99"),"144Hz • HDR600"));@GetMapping public List<Product>all(@RequestParam(required=false)String category){return category==null?products:products.stream().filter(p->p.category().equalsIgnoreCase(category)).toList();}@GetMapping("/{id}")public Product one(@PathVariable long id){return products.stream().filter(p->p.id()==id).findFirst().orElseThrow();}public record Product(long id,String name,String category,BigDecimal price,String specs){}}
